/**
 * Phase 35 — Native iOS Video Editor (ClipForge) tests.
 *
 * The editor itself is Swift code generated by
 * server/ios/videoEditorGenerator.ts. These tests verify the
 * generated project structurally and semantically:
 * - it is a complete Phase 25 Xcode project whose pbxproj
 *   references exactly the editor's Swift sources (validator-clean)
 *   and no WebView anywhere;
 * - media import is picker-based (PhotosPicker for video/image,
 *   the document picker for audio) and probes metadata with
 *   AVFoundation, never decoding whole files into memory;
 * - the Swift EditorOps implement the same operation set as the
 *   server engine's editingOps dispatcher;
 * - the Swift project model's JSON field names round-trip through
 *   the SERVER's own serializer/deserializer (interop proof);
 * - preview is AVPlayer over an AVMutableComposition; export is
 *   AVAssetExportSession with progress polling and cancelExport();
 * - persistence (ProjectStore) and the SquadForge API client target
 *   the real Phase 31 endpoints and their SerializedVideoProject
 *   envelope;
 * - the generate route stores the project for the owning user only.
 *
 * Genuine Xcode compilation of the generated app is proven by the
 * Phase 35 CI workflow (scripts/phase35-genuine-build.ts) on a
 * macOS runner, because native iOS builds are impossible on this
 * host (the Phase 25 pipeline reports environment-unavailable here
 * by design).
 */
import { test, describe, before, after } from 'node:test';
import assert from 'node:assert';
import http from 'node:http';
import { AddressInfo } from 'node:net';
import express from 'express';
import { db } from '../server/store.js';
import {
  generateVideoEditorProject,
  getVideoEditorConfig
} from '../server/ios/videoEditorGenerator.js';
import { IosProjectValidator } from '../server/ios/iosProjectValidator.js';
import { createIosRouter } from '../server/ios/iosRoutes.js';
import {
  serializeVideoProject,
  deserializeVideoProject
} from '../server/videoEditor/timeline.js';
import type { VideoProject } from '../server/videoEditor/types.js';

const config = getVideoEditorConfig();
const files = generateVideoEditorProject(config);
const sw = (suffix: string): string => {
  const key = Object.keys(files).find(k => k.endsWith(suffix));
  assert.ok(key, `generated file ${suffix} missing`);
  return files[key!];
};

describe('Phase 35: generated project completeness', () => {
  test('is a complete Phase 25 project plus the editor sources', () => {
    for (const expected of [
      'ClipForge.xcodeproj/project.pbxproj',
      'ClipForge/Info.plist',
      'ClipForge/Assets.xcassets/AppIcon.appiconset/AppIcon1024.png'
    ]) {
      assert.ok(files[expected], `missing ${expected}`);
    }
    sw('/ClipForgeApp.swift');
    sw('/ContentView.swift');
    sw('/Editor/EditorModels.swift');
    sw('/Editor/EditorOps.swift');
    sw('/Editor/ProjectStore.swift');
    sw('/Editor/SquadForgeApi.swift');
    sw('/Player/PreviewPlayer.swift');
    sw('/Export/VideoExporter.swift');
    sw('/UI/EditorViewModel.swift');
    sw('/UI/EditorView.swift');
    assert.ok(files['VIDEO_EDITOR_README.md']);
    // The starter app's content files are gone, not shipped dead.
    for (const gone of ['ItemDetailView.swift', 'ItemRowView.swift', 'Item.swift', 'ItemListViewModel.swift']) {
      assert.ok(!Object.keys(files).some(k => k.endsWith(gone)), `${gone} must not be generated`);
    }
  });

  test('passes the Phase 25 structural validator and the pbxproj references the editor groups', () => {
    const validation = IosProjectValidator.validateProjectFiles(files, config);
    assert.deepEqual(validation.errors, []);
    assert.equal(validation.valid, true);
    const pbx = files['ClipForge.xcodeproj/project.pbxproj'];
    for (const group of ['/* Editor */', '/* Player */', '/* Export */', '/* UI */']) {
      assert.ok(pbx.includes(group), `pbxproj missing group ${group}`);
    }
    for (const gone of ['/* Views */', '/* Models */', '/* Item.swift */']) {
      assert.ok(!pbx.includes(gone), `pbxproj must not reference ${gone}`);
    }
    assert.ok(pbx.includes('SDKROOT = iphoneos;'));
  });

  test('config carries the photo-library permission and its Info.plist usage string', () => {
    assert.deepEqual(config.permissions, ['photoLibrary']);
    assert.equal(config.bundleId, 'com.squadforge.clipforge');
    assert.ok(files['ClipForge/Info.plist'].includes('NSPhotoLibraryUsageDescription'));
  });

  test('generated Swift has no broken multi-line string literals', () => {
    // Same regression class as the Phase 34 Kotlin failure: a
    // single-backslash escape in a generator template would turn a
    // Swift "\n" into a real line break inside a string literal.
    // Escape- and comment-aware scanner (string and char literals);
    // every literal must close on the line it opens.
    const unterminated = (content: string): number[] => {
      const bad: number[] = [];
      let inStr = false, inChar = false, inBlock = false, esc = false;
      content.split('\n').forEach((line, i) => {
        let inLineComment = false;
        for (let j = 0; j < line.length; j++) {
          const c = line[j], n = line[j + 1] ?? '';
          if (inLineComment) break;
          if (inBlock) { if (c === '*' && n === '/') { inBlock = false; j++; } continue; }
          if (esc) { esc = false; continue; }
          if ((inStr || inChar) && c === '\\') { esc = true; continue; }
          if (!inStr && !inChar) {
            if (c === '/' && n === '/') { inLineComment = true; break; }
            if (c === '/' && n === '*') { inBlock = true; j++; continue; }
            if (c === '"') inStr = true;
            else if (c === "'") inChar = true;
          } else if (inStr && c === '"') inStr = false;
          else if (inChar && c === "'") inChar = false;
        }
        if (inStr || inChar) { bad.push(i + 1); inStr = false; inChar = false; esc = false; }
      });
      return bad;
    };
    for (const [path, content] of Object.entries(files)) {
      if (!path.endsWith('.swift')) continue;
      assert.deepEqual(unterminated(content), [], `${path} has unterminated literals`);
    }
  });

  test('no WebView anywhere in the generated app', () => {
    for (const [path, content] of Object.entries(files)) {
      if (path.endsWith('.swift')) {
        assert.ok(!content.includes('WebView'), `${path} uses WebView`);
        assert.ok(!content.includes('WKWebView'), `${path} uses WKWebView`);
        assert.ok(!content.includes('WebKit'), `${path} imports WebKit`);
      }
    }
  });
});

describe('Phase 35: media import, preview, export wiring', () => {
  test('import uses PhotosPicker + the document picker and copies media into the sandbox', () => {
    const view = sw('/UI/EditorView.swift');
    assert.ok(view.includes('.photosPicker('));
    assert.ok(view.includes('.any(of: [.videos, .images])'));
    assert.ok(view.includes('.fileImporter('));
    assert.ok(view.includes('UTType') || view.includes('UniformTypeIdentifiers'));
    const vm = sw('/UI/EditorViewModel.swift');
    // The picker/transfer types live in CoreTransferable + PhotosUI
    // and the picker surface in SwiftUI — CI run 45678088776 failed
    // with all three "cannot find type in scope" until the ViewModel
    // imported them explicitly.
    for (const mod of ['import CoreTransferable', 'import PhotosUI', 'import SwiftUI']) {
      assert.ok(vm.includes(mod), `EditorViewModel must ${mod}`);
    }
    assert.ok(vm.includes('FileRepresentation(contentType: .movie)'), 'movie transfer copies the picked file');
    assert.ok(vm.includes('startAccessingSecurityScopedResource'), 'document-picker files are copied out of the security scope');
    assert.ok(vm.includes('asset.load(.duration)'), 'metadata is probed with AVFoundation');
    assert.ok(vm.includes('loadTracks(withMediaType:'), 'track presence is probed, not decoded');
    // No whole-file loading of media anywhere in the app sources.
    for (const suffix of ['/UI/EditorViewModel.swift', '/Player/PreviewPlayer.swift', '/Export/VideoExporter.swift']) {
      const src = sw(suffix);
      assert.ok(!src.includes('Data(contentsOf:'), `${suffix} must not read whole media files into memory`);
    }
  });

  test('preview is AVPlayer over a timeline composition', () => {
    const player = sw('/Player/PreviewPlayer.swift');
    assert.ok(player.includes('AVMutableComposition'));
    assert.ok(player.includes('insertTimeRange'));
    assert.ok(player.includes('AVMutableAudioMix'));
    assert.ok(player.includes('replaceCurrentItem'));
    const view = sw('/UI/EditorView.swift');
    assert.ok(view.includes('VideoPlayer(player:'), 'preview surface is the AVKit VideoPlayer');
  });

  test('export is AVAssetExportSession with progress polling and cancellation', () => {
    const exporter = sw('/Export/VideoExporter.swift');
    assert.ok(exporter.includes('AVAssetExportSession'));
    assert.ok(exporter.includes('AVAssetExportPresetHighestQuality'));
    assert.ok(exporter.includes('session.outputFileType = .mp4'));
    assert.ok(exporter.includes('Timer.scheduledTimer'), 'progress is polled');
    assert.ok(exporter.includes('active.progress'), 'progress comes from the export session itself');
    assert.ok(exporter.includes('session?.cancelExport()'));
    assert.ok(exporter.includes('ExportCancelledError'));
    assert.ok(exporter.includes('AVMutableVideoComposition'), 'target sizes render through a video composition');
    // Export limitations are stated in code, not hidden.
    assert.ok(exporter.includes('were not composited into the export'));
    assert.ok(exporter.includes('render as cuts'));
    assert.ok(exporter.includes('not burned into the app export'));
  });

  test('persistence saves atomically and recovers the last project', () => {
    const store = sw('/Editor/ProjectStore.swift');
    assert.ok(store.includes('"projects"'));
    assert.ok(store.includes('.json.tmp'), 'writes go through a temp file');
    assert.ok(store.includes('replaceItemAt'), 'temp file is atomically replaced into place');
    assert.ok(store.includes('last_project.txt'));
    assert.ok(store.includes('func loadLast()'));
  });

  test('API client targets the real Phase 31 endpoints and envelope', () => {
    const api = sw('/Editor/SquadForgeApi.swift');
    assert.ok(api.includes('"/project/load"'));
    assert.ok(api.includes('"/project/save"'));
    assert.ok(api.includes('"/api/builds/"'));
    assert.ok(api.includes('URLSession.shared.data(for:'));
    // The server speaks SerializedVideoProject; the client translates.
    assert.ok(api.includes('"squadforge-video-project"'));
    assert.ok(api.includes('serialized["media"]'), 'load merges the envelope media into the project');
    assert.ok(api.includes('removeValue(forKey: "media")'), 'save splits media into the envelope');
  });
});

describe('Phase 35: editing-operation parity with the server engine', () => {
  test('Swift EditorOps cover the server dispatcher operations', () => {
    const ops = sw('/Editor/EditorOps.swift');
    // Server editingOps.ts cases: addTrack, addClip, trim, split,
    // move, remove, setVolume, setSpeed, addText, updateText,
    // removeText, addTransition, setTrackVolume, setTrackMuted
    // (plus the caption ops from Phase 29).
    for (const fn of [
      'func addTrack', 'func addClip', 'func trimClip', 'func splitClip',
      'func moveClip', 'func removeClip', 'func setClipVolume',
      'func setClipSpeed', 'func addText', 'func updateText',
      'func removeText', 'func addCaption', 'func removeCaption',
      'func addTransition', 'func setTrackVolume', 'func setTrackMuted',
      'func captionsToSrt'
    ]) {
      assert.ok(ops.includes(fn), `EditorOps missing ${fn}`);
    }
    // The split math and the overlap rule are the server's.
    assert.ok(ops.includes('clip.sourceIn + offset * clip.speedOrDefault()'), 'split uses sourceIn + offset x speed');
    assert.ok(ops.includes('1e-6'), 'overlap check uses the shared epsilon');
    // Swift string interpolation survived generator escaping intact.
    assert.ok(ops.includes('\\(index + 1)'), 'SRT numbering interpolates');
  });

  test('project JSON written by the Swift model parses in the server engine', () => {
    // A fixture with exactly the field names EditorModels.swift
    // encodes (and decodes).
    const fixture = {
      id: 'project_swift1',
      name: 'Swift Round Trip',
      width: 1280,
      height: 720,
      fps: 30,
      media: [
        { id: 'm1', path: 'media/import_ab12cd34.mov', durationSec: 12.5, hasVideo: true, hasAudio: true, width: 1920, height: 1080, kind: 'video' }
      ],
      tracks: [
        {
          id: 't1', kind: 'video', name: 'Video 1', volume: 1, clips: [
            {
              id: 'c1', mediaId: 'm1', trackStart: 0, sourceIn: 1, sourceOut: 6,
              volume: 0.8, effect: 'none', speed: 1.5,
              transform: { x: 10, y: 20, scale: 1, rotationDeg: 0, opacity: 1 }
            }
          ]
        },
        { id: 't2', kind: 'audio', name: 'Audio 1', muted: false, clips: [] }
      ],
      transitions: [{ afterClipId: 'c1', type: 'crossfade', durationSec: 0.5 }],
      texts: [{ id: 'x1', text: 'Hello', trackStart: 1, durationSec: 2, x: 40, y: 40, fontSize: 48, color: '#FFFFFF' }],
      captions: [{ id: 'cap1', startSec: 0.5, endSec: 2.5, text: 'First line' }]
    };
    const parsed = deserializeVideoProject({ format: 'squadforge-video-project', version: 1, project: fixture, media: fixture.media } as any);
    assert.equal(parsed.project.name, 'Swift Round Trip');
    assert.equal(parsed.project.tracks[0].clips[0].speed, 1.5);
    assert.equal(parsed.project.texts?.[0].text, 'Hello');
    assert.equal(parsed.project.captions?.[0].text, 'First line');

    // And the server's serializer emits every field the Swift
    // decoder reads.
    const serverProject: VideoProject = parsed.project;
    const out = serializeVideoProject(serverProject, parsed.mediaAssets) as any;
    for (const key of ['id', 'name', 'width', 'height', 'fps', 'tracks', 'media', 'transitions', 'texts', 'captions']) {
      assert.ok(key in out.project || key in out, `server serializer missing ${key}`);
    }
    const clip = out.project.tracks[0].clips[0];
    for (const key of ['id', 'mediaId', 'trackStart', 'sourceIn', 'sourceOut', 'volume']) {
      assert.ok(key in clip, `server clip missing ${key}`);
    }
  });
});

describe('Phase 35: generate route', () => {
  let owner: any;
  let foreigner: any;
  let build: any;
  let baseUrl: string;
  let server: http.Server;

  before(async () => {
    const stamp = Date.now();
    owner = { id: `usr_p35_${stamp}`, email: 'p35@squadforge.dev', name: 'P35 Owner' };
    foreigner = { id: `usr_p35f_${stamp}`, email: 'p35f@squadforge.dev', name: 'P35 Foreign' };
    db.saveUser(owner as any);
    db.saveUser(foreigner as any);
    build = {
      id: `bld_p35_${stamp}`,
      userId: owner.id,
      idea: 'ClipForge iOS editor build',
      status: 'idle',
      progress: 0,
      logs: [],
      files: [],
      createdAt: stamp,
      updatedAt: stamp
    };
    db.saveBuild(build as any);

    const app = express();
    app.use(express.json());
    app.use((req: any, _res: any, next: any) => {
      req.user = req.headers['x-test-user'] === 'foreign' ? foreigner : owner;
      next();
    });
    const passAuth = ((_req: any, _res: any, next: any) => next()) as any;
    const verifyOwnership = (req: any, res: any, buildId: string) => {
      const found: any = db.getBuild(buildId);
      if (!found) {
        res.status(404).json({ error: 'Build not found' });
        return null;
      }
      if (found.userId !== req.user?.id) {
        res.status(403).json({ error: 'Forbidden' });
        return null;
      }
      return found;
    };
    app.use('/api/builds/:id/ios', createIosRouter({ requireAuth: passAuth, verifyBuildOwnership: verifyOwnership as any }));

    server = http.createServer(app);
    const port = await new Promise<number>(resolve =>
      server.listen(0, '127.0.0.1', () => resolve((server.address() as AddressInfo).port))
    );
    baseUrl = `http://127.0.0.1:${port}`;
  });

  test('owner generates the editor project; files land in the build', async () => {
    const res = await fetch(`${baseUrl}/api/builds/${build.id}/ios/video-editor/generate`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({})
    });
    const body: any = await res.json();
    assert.equal(res.status, 200, JSON.stringify(body));
    assert.equal(body.success, true);
    assert.equal(body.editor, 'clipforge');
    assert.equal(body.validation.valid, true);
    assert.ok(body.fileCount >= 18, `expected the full project, got ${body.fileCount}`);
    const stored = db.getAllFiles(build.id) as any[];
    const paths = stored.map(f => f.path);
    assert.ok(paths.some(p => p.endsWith('/Export/VideoExporter.swift')), 'exporter stored');
    assert.ok(paths.some(p => p === 'ClipForge.xcodeproj/project.pbxproj'), 'pbxproj stored');
  });

  after(() => {
    (server as any)?.closeAllConnections?.();
    server?.close();
  });

  test('foreign user cannot generate into someone else\'s build', async () => {
    const res = await fetch(`${baseUrl}/api/builds/${build.id}/ios/video-editor/generate`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-test-user': 'foreign' },
      body: JSON.stringify({})
    });
    assert.ok(res.status === 403 || res.status === 404, `foreign user got ${res.status}`);
  });
});
